import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxButton,
  JxChip,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over';

interface Project {
  id: string;
  name: string;
  quotaUsed: number;
  status: ProjectStatus;
}

const STATUSES: Array<{ value: ProjectStatus; label: string; tone: 'success' | 'warning' | 'danger' }> = [
  { value: 'active', label: 'Активен', tone: 'success' },
  { value: 'paused', label: 'На паузе', tone: 'warning' },
  { value: 'over', label: 'Превышение', tone: 'danger' },
];

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Каталог', quotaUsed: 42, status: 'active' },
  { id: 'p2', name: 'Биллинг', quotaUsed: 96, status: 'over' },
  { id: 'p3', name: 'Аналитика', quotaUsed: 18, status: 'paused' },
  { id: 'p4', name: 'Личный кабинет', quotaUsed: 61, status: 'active' },
  { id: 'p5', name: 'Импорт данных', quotaUsed: 88, status: 'over' },
  { id: 'p6', name: 'Уведомления', quotaUsed: 7, status: 'paused' },
  { id: 'p7', name: 'Поиск', quotaUsed: 55, status: 'active' },
  { id: 'p8', name: 'Отчёты', quotaUsed: 73, status: 'active' },
  { id: 'p9', name: 'Интеграции', quotaUsed: 34, status: 'paused' },
  { id: 'p10', name: 'Мобильное API', quotaUsed: 91, status: 'over' },
  { id: 'p11', name: 'Документы', quotaUsed: 26, status: 'active' },
  { id: 'p12', name: 'Витрина', quotaUsed: 80, status: 'over' },
];

const PAGE_SIZE = 5;

export default function ProjectQuotaPanel() {
  const [selected, setSelected] = useState<ProjectStatus[]>([]);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setSelected((current) =>
      current.includes(status) ? current.filter((item) => item !== status) : [...current, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setSelected([]);
    setPage(1);
  };

  const filtered = useMemo(
    () => (selected.length === 0 ? PROJECTS : PROJECTS.filter((project) => selected.includes(project.status))),
    [selected],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const safePage = Math.min(page, pageCount);
  const visible = filtered.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE);

  return (
    <section style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {STATUSES.map((status) => {
          const active = selected.includes(status.value);
          return (
            <JxChip
              key={status.value}
              active={active}
              removable={active}
              onRemove={() => toggleStatus(status.value)}
              onClick={() => toggleStatus(status.value)}
            >
              {status.label}
            </JxChip>
          );
        })}
      </div>

      {visible.length === 0 ? (
        <JxEmptyState
          title="Ничего не найдено"
          message="Под выбранные статусы не подходит ни один проект."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <ul style={{ listStyle: 'none', margin: 0, padding: 0, display: 'flex', flexDirection: 'column', gap: '8px' }}>
            {visible.map((project) => {
              const status = STATUSES.find((item) => item.value === project.status)!;
              return (
                <li
                  key={project.id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '16px',
                    padding: '12px 16px',
                    background: 'var(--jx-surface)',
                    border: '1px solid var(--jx-border)',
                    borderRadius: 'var(--jx-r)',
                  }}
                >
                  <span style={{ flex: 1, color: 'var(--jx-text)', fontFamily: 'var(--jx-font-sans)' }}>
                    {project.name}
                  </span>
                  <JxProgressCircle value={project.quotaUsed} showValue aria-label={`Квота: ${project.quotaUsed}%`} />
                  <JxBadge tone={status.tone} dot>
                    {status.label}
                  </JxBadge>
                </li>
              );
            })}
          </ul>
          <JxPagination total={pageCount} page={safePage} onPageChange={setPage} />
        </>
      )}
    </section>
  );
}

